// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(112000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    await page.goto(`${baseUrl}/`);

    const toolButton = (tool: string) =>
        page.locator(`.App-toolbar label.ToolIcon:has([data-testid="toolbar-${tool}"])`);

    await expect(toolButton("rectangle")).toBeVisible();
    await page
        .locator('[data-testid="toolbar-rectangle"]')
        .waitFor({ state: "attached", timeout: 10000 });

    // Click inside the Rectangle tool's OWN box, 3px in from its right edge.
    // The point is derived from the live box so it stays inside Rectangle
    // whatever spacing the toolbar is laid out with.
    const rectangleBox = await toolButton("rectangle").boundingBox();
    if (!rectangleBox) {
        throw new Error("Rectangle tool button has no bounding box");
    }
    await page.mouse.click(
        rectangleBox.x + rectangleBox.width - 3,
        rectangleBox.y + rectangleBox.height / 2,
    );

    // Clicking a tool button selects that tool: Actions.tsx renders each tool
    // with checked={activeTool.type === value}.
    await expect(page.getByTestId("toolbar-rectangle")).toBeChecked();
    await expect(page.getByTestId("toolbar-diamond")).not.toBeChecked();
    await expect(page.getByTestId("toolbar-selection")).not.toBeChecked();

    // No tool button may overlap its right neighbour, or the neighbour steals
    // part of its click target.
    const shapeTools = ["selection", "rectangle", "diamond", "ellipse", "arrow", "line", "freedraw", "text", "image", "eraser"];
    await expect(page.locator(".App-toolbar label.ToolIcon")).toHaveCount(12);

    const toolBoxes: { tool: string; x: number; width: number }[] = [];
    for (const tool of shapeTools) {
        const box = await toolButton(tool).boundingBox();
        if (!box) {
            throw new Error(`Tool button toolbar-${tool} has no bounding box`);
        }
        toolBoxes.push({ tool, x: box.x, width: box.width });
    }

    for (let i = 0; i < toolBoxes.length - 1; i++) {
        const left = toolBoxes[i];
        const right = toolBoxes[i + 1];
        const edgeDistance = right.x - (left.x + left.width);
        expect(
            edgeDistance,
            `gap between toolbar-${left.tool} and toolbar-${right.tool}`,
        ).toBeGreaterThanOrEqual(0);
    }

    await expect(pageErrors).toHaveLength(0);
});
